content.text:
/* BEM 방식 — 특이도: (0,0,1,0) */
.card__title { color: black; }

/* 비BEM 방식 — 특이도: (0,0,1,1) */
.card h2 { color: black; }

/* 비BEM 방식 — 특이도: (0,1,0,0) */
#card-title { color: black; }

.button {
  background: gray;
  color: white;
  padding: 8px 16px;
}

.button--primary {
  background: blue;    /* 같은 특이도, 뒤에 선언돼서 덮어씀 */
}

.button--large {
  padding: 12px 24px;  /* 같은 특이도, 정상적으로 덮어씀 */
}

// 구조적인 SCSS 중첩 구조

.card {
  background: white;

  &__title {        // ← 컴파일하면 .card__title
    font-size: 20px;
  }

  &__image {        // ← .card__image
    width: 100%;
  }

  &--featured {     // ← .card--featured (Modifier)
    border: 2px solid blue;
  }

  &--featured &__title {  // ← .card--featured .card__title
    color: blue;
  }
}

/* 라이브러리 수준에서 명확한 네임스페이스 */
.ds-button { }           /* ds = design system */
.ds-button--primary { }
.ds-card__title { }

/* Boolean Modifier */
.button--disabled { }

/* Key-Value Modifier */
.button--size-large { }    /* size: large */
.button--theme-dark { }    /* theme: dark */
